(7212329, 1111030, 147314, '<td valign="top">Water drops on the rose are cool, but the ones in the background are somewhat distracting<br/><br/><i>Message edited by author 2014-05-05 03:09:36.</i></td>', 'Water drops on the rose are cool, but the ones in the background are somewhat distracting', '2014-05-04 19:49:27.000000', '2014-05-05 04:09:36.000000', 1),
