(7212357, 1111021, 19944, '<td valign="top">Now I can''t get that song out of my brain.  Thanks.</td>', 'Now I can''t get that song out of my brain.  Thanks.', '2014-05-04 20:56:22.000000', NULL, 1),
(7212359, 1110933, 19944, '<td valign="top">I''m very stingy with my 10 votes.  This image just grabbed me and made me give it a 10.  I can''t put my finger on what, exactly, it is that grabs me, but I can''t stop looking at it.</td>', 'I''m very stingy with my 10 votes.  This image just grabbed me and made me give it a 10.  I can''t put my finger on what, exactly, it is that grabs me, but I can''t stop looking at it.', '2014-05-04 21:03:32.000000', NULL, 1),
(7212360, 1110770, 19944, '<td valign="top">For me, the light post kills it.  A 5 with the light post, at least a 6 without it.</td>', 'For me, the light post kills it.  A 5 with the light post, at least a 6 without it.', '2014-05-04 21:06:30.000000', NULL, 1),
(7212361, 1110980, 19944, '<td valign="top">I almost low voted for the lack of focus, but then I hesitated, and didn''t.  The longer I look, the more it grows on me.</td>', 'I almost low voted for the lack of focus, but then I hesitated, and didn''t.  The longer I look, the more it grows on me.', '2014-05-04 21:08:38.000000', NULL, 1),
(7212364, 1109944, 19944, '<td valign="top">Not a big fan of the subject, but it is well lit and well shot.</td>', 'Not a big fan of the subject, but it is well lit and well shot.', '2014-05-04 21:15:23.000000', NULL, 1),
(7212395, 1110886, 100831, '<td valign="top">I hope. This image takes on a different dimension.</td>', 'I hope. This image takes on a different dimension.', '2014-05-04 22:23:06.000000', NULL, 1),
(7212396, 1110818, 100831, '<td valign="top">Such joy! Great catch</td>', 'Such joy! Great catch', '2014-05-04 22:24:08.000000', NULL, 1),
(7212412, 1110892, 147861, '<td valign="top">I really like the unusual point of view.  I do find the sign in the lower right a bit distracting, though.</td>', 'I really like the unusual point of view.  I do find the sign in the lower right a bit distracting, though.', '2014-05-04 22:46:42.000000', NULL, 1),
(7212413, 1110818, 147861, '<td valign="top">I love the look of joy on her face.  I would like to see the whole photo a bit lighter.</td>', 'I love the look of joy on her face.  I would like to see the whole photo a bit lighter.', '2014-05-04 22:48:59.000000', NULL, 1),
(7212415, 1110976, 147861, '<td valign="top">Nice shot.  I think it would be better with a little more catch light in the eye.</td>', 'Nice shot.  I think it would be better with a little more catch light in the eye.', '2014-05-04 22:51:22.000000', NULL, 1),
(7212416, 1110956, 147861, '<td valign="top">Nice contrast between the soft fur and the cold, hard metal (plastic?) of the chair.</td>', 'Nice contrast between the soft fur and the cold, hard metal (plastic?) of the chair.', '2014-05-04 22:52:47.000000', NULL, 1),
(7212417, 1110997, 147861, '<td valign="top">I love the tones of this beautiful abstract</td>', 'I love the tones of this beautiful abstract', '2014-05-04 22:53:36.000000', NULL, 1),
(7212418, 1110701, 147861, '<td valign="top">Beautiful symmetry and shapes,lines, and different tones</td>', 'Beautiful symmetry and shapes,lines, and different tones', '2014-05-04 22:57:00.000000', NULL, 1),
(7212424, 1110814, 147861, '<td valign="top">I like the graininess of this.  It almost looks like a painting.  I do find the bars on the left side a bit distracting and would like to see some of the face</td>', 'I like the graininess of this.  It almost looks like a painting.  I do find the bars on the left side a bit distracting and would like to see some of the face', '2014-05-04 23:05:05.000000', NULL, 1),
(7212425, 1111027, 147861, '<td valign="top">I like the simplicity of this, and the variety of textures</td>', 'I like the simplicity of this, and the variety of textures', '2014-05-04 23:06:19.000000', NULL, 1),
(7212426, 1110976, 100831, '<td valign="top">Wonderful details</td>', 'Wonderful details', '2014-05-04 23:06:40.000000', NULL, 1),
(7212428, 1111029, 100831, '<td valign="top">Such attitude</td>', 'Such attitude', '2014-05-04 23:07:21.000000', NULL, 1),
(7212430, 1110058, 147861, '<td valign="top">Nice idea, but I find the highlights on the walk way are just too bright</td>', 'Nice idea, but I find the highlights on the walk way are just too bright', '2014-05-04 23:07:56.000000', NULL, 1),
(7212432, 1109945, 100831, '<td valign="top">Such a personality</td>', 'Such a personality', '2014-05-04 23:08:10.000000', NULL, 1),
(7212433, 1111002, 173844, '<td valign="top">A happy marriage between a wonderfully complex sky of a continuum of tones and a very interesting foreground of buildings, trees and cropland lit by that heightened light that presages rain.  Textures galore.  Terrific stuff.</td>', 'A happy marriage between a wonderfully complex sky of a continuum of tones and a very interesting foreground of buildings, trees and cropland lit by that heightened light that presages rain.  Textures galore.  Terrific stuff.', '2014-05-04 23:08:25.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7212435, 1110691, 147861, '<td valign="top">I think the photo would be better if cropped a little tighter on the left</td>', 'I think the photo would be better if cropped a little tighter on the left', '2014-05-04 23:08:55.000000', NULL, 1),
(7212436, 1110964, 114285, '<td valign="top">Interesting still life, already voted!</td>', 'Interesting still life, already voted!', '2014-05-04 23:09:17.000000', NULL, 1),
(7212438, 1110683, 100831, '<td valign="top">Not boring at all.</td>', 'Not boring at all.', '2014-05-04 23:09:58.000000', NULL, 1),
(7212439, 1110822, 147861, '<td valign="top">Nice photo, but I find the railing distracting and think the photo would be better if much of the railing were cropped out</td>', 'Nice photo, but I find the railing distracting and think the photo would be better if much of the railing were cropped out', '2014-05-04 23:10:28.000000', NULL, 1),
(7212448, 1110878, 173844, '<td valign="top">Beautiful shot artfully observed.  The screen through which this is photographed transforms the scene into a filigree tapestry.  The dog, striped with sunlight, is in classic repose.  Looking through one window with its curtained corner, through the languid interior and out an opposite, curtained window, graced with a pitcher and a photograph of what my imagination suggests is the Dalai Lama, is a journey of prodigious delight.</td>', 'Beautiful shot artfully observed.  The screen through which this is photographed transforms the scene into a filigree tapestry.  The dog, striped with sunlight, is in classic repose.  Looking through one window with its curtained corner, through the languid interior and out an opposite, curtained window, graced with a pitcher and a photograph of what my imagination suggests is the Dalai Lama, is a journey of prodigious delight.', '2014-05-04 23:22:33.000000', NULL, 1),
(7212450, 1110818, 23484, '<td valign="top">The joy in the life of a child.</td>', 'The joy in the life of a child.', '2014-05-04 23:24:54.000000', NULL, 1),
(7212453, 1110744, 50695, '<td valign="top">striking photo. well seen.</td>', 'striking photo. well seen.', '2014-05-04 23:27:53.000000', NULL, 1),
(7212454, 1111005, 50695, '<td valign="top">beautiful portrait. well composed.</td>', 'beautiful portrait. well composed.', '2014-05-04 23:28:04.000000', NULL, 1),
(7212455, 1111029, 50695, '<td valign="top">lovely</td>', 'lovely', '2014-05-04 23:28:13.000000', NULL, 1),
(7212456, 1110744, 173844, '<td valign="top">Handsome study of these living, breathing pipes, stacked like asparagus, in terrific perspective.</td>', 'Handsome study of these living, breathing pipes, stacked like asparagus, in terrific perspective.', '2014-05-04 23:28:15.000000', NULL, 1),
(7212457, 1110052, 50695, '<td valign="top">intimate</td>', 'intimate', '2014-05-04 23:28:39.000000', NULL, 1),
