(7212462, 1110892, 50695, '<td valign="top">good catch</td>', 'good catch', '2014-05-04 23:29:12.000000', NULL, 1),
(7212463, 1111029, 173844, '<td valign="top">Truly adorable study of gangly infancy.  Beautiful bokeh.</td>', 'Truly adorable study of gangly infancy.  Beautiful bokeh.', '2014-05-04 23:29:48.000000', NULL, 1),
(7212464, 1110896, 50695, '<td valign="top">lovely and interesting effect. original yet easy to look at.</td>', 'lovely and interesting effect. original yet easy to look at.', '2014-05-04 23:29:55.000000', NULL, 1),
