(7213228, 1110683, 173844, '<td valign="top">I couldn''t make up my mind if this is miraculous or humdrum. Boink!  The commentators have way convinced me of the former.</td>', 'I couldn''t make up my mind if this is miraculous or humdrum. Boink!  The commentators have way convinced me of the former.', '2014-05-06 12:06:35.000000', NULL, 0),
(7213230, 1110725, 173844, '<td valign="top">I gave this a high rating but somehow missed commenting on it.  It''s really engaging and also a fine photograph.  The warmth and softness of the goats are palpable.  The centered composition is well chosen for the solidity it conveys.  The surrounding textures of wood and straw create a comforting rhythm.  It''s wonderfully peaceful and innocent.</td>', 'I gave this a high rating but somehow missed commenting on it.  It''s really engaging and also a fine photograph.  The warmth and softness of the goats are palpable.  The centered composition is well chosen for the solidity it conveys.  The surrounding textures of wood and straw create a comforting rhythm.  It''s wonderfully peaceful and innocent.', '2014-05-06 12:13:57.000000', NULL, 0),
(7213231, 1110770, 173844, '<td valign="top">Wonderfully rhythmic. I like the light pole as counterpoint.  Your comment adds to the mood.</td>', 'Wonderfully rhythmic. I like the light pole as counterpoint.  Your comment adds to the mood.', '2014-05-06 12:17:02.000000', NULL, 0),
(7213241, 1110961, 173844, '<td valign="top">As an incredible photograph this is one of my three favorites, but gave it a lower rating due to the fact that I feel the sepia treatment edges it out of the spirit of the challenge --  black and white.  I think it would have been just as delicately beautiful and powerful in black and white.</td>', 'As an incredible photograph this is one of my three favorites, but gave it a lower rating due to the fact that I feel the sepia treatment edges it out of the spirit of the challenge --  black and white.  I think it would have been just as delicately beautiful and powerful in black and white.', '2014-05-06 12:26:09.000000', NULL, 0),
(7213243, 1110956, 173844, '<td valign="top">Nicely composed, elegant portrait.</td>', 'Nicely composed, elegant portrait.', '2014-05-06 12:28:18.000000', NULL, 0),
(7213247, 1110520, 173844, '<td valign="top">I like this image very much but could not decide if it is strictly black and white.  Signed, Confused and Anal Retentive</td>', 'I like this image very much but could not decide if it is strictly black and white.  Signed, Confused and Anal Retentive', '2014-05-06 12:34:19.000000', NULL, 0),
(7213248, 1110709, 173844, '<td valign="top">Extremely pretty, rhythmic and magical.</td>', 'Extremely pretty, rhythmic and magical.', '2014-05-06 12:35:36.000000', NULL, 0),
(7213257, 1111005, 173844, '<td valign="top">Re-observed, re-evaluated and really appreciated.  Sweet in many ways --  composition, tonality, textures and subject.  That''s a good-looking chicken.  I did the math and had I given this image a rating more suited to its merit (subjective, as always) it would have advanced one place in the ranking.  Sorry about that.</td>', 'Re-observed, re-evaluated and really appreciated.  Sweet in many ways --  composition, tonality, textures and subject.  That''s a good-looking chicken.  I did the math and had I given this image a rating more suited to its merit (subjective, as always) it would have advanced one place in the ranking.  Sorry about that.', '2014-05-06 13:11:43.000000', NULL, 0),
(7213265, 1110901, 173844, '<td valign="top">Great feeling of context for this man at work.  So many textures and tones.  I especially like the composition wherein the gentleman fills the frame so well in his wholly appropriate posture.</td>', 'Great feeling of context for this man at work.  So many textures and tones.  I especially like the composition wherein the gentleman fills the frame so well in his wholly appropriate posture.', '2014-05-06 14:00:15.000000', NULL, 0),
(7213267, 1110865, 96751, '<td valign="top">So delicate yet animated! LOVE this.  Congrats on the blue, Wendy</td>', 'So delicate yet animated! LOVE this.  Congrats on the blue, Wendy', '2014-05-06 14:01:52.000000', NULL, 0),
(7213268, 1110924, 96751, '<td valign="top">That sand is incredible. Congrats on the ribbon.</td>', 'That sand is incredible. Congrats on the ribbon.', '2014-05-06 14:02:55.000000', NULL, 0),
(7213269, 1110818, 96751, '<td valign="top">How fun is this!!! Congrats on the ribbon, Paul.</td>', 'How fun is this!!! Congrats on the ribbon, Paul.', '2014-05-06 14:03:42.000000', NULL, 0),
(7213270, 1110746, 96751, '<td valign="top">I''m so envious of your view :)  Congrats on the HM</td>', 'I''m so envious of your view :)  Congrats on the HM', '2014-05-06 14:04:33.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7213271, 1110917, 96751, '<td valign="top">Cottages there seem to be a LOT larger than the ones around here :)</td>', 'Cottages there seem to be a LOT larger than the ones around here :)', '2014-05-06 14:05:27.000000', NULL, 0),
(7213272, 1111002, 96751, '<td valign="top">Love that the silo structure appears to be emerging from an underground silo :)</td>', 'Love that the silo structure appears to be emerging from an underground silo :)', '2014-05-06 14:06:28.000000', NULL, 0),
(7213273, 1110455, 96751, '<td valign="top">Such a splendid portrait</td>', 'Such a splendid portrait', '2014-05-06 14:07:01.000000', NULL, 0),
(7213276, 1110908, 173844, '<td valign="top">I understand Tiny''s observations, but still I like this image, especially the cumulus clouds, and find in it a sense of peaceful balance.</td>', 'I understand Tiny''s observations, but still I like this image, especially the cumulus clouds, and find in it a sense of peaceful balance.', '2014-05-06 14:10:04.000000', NULL, 0),
(7213277, 1110908, 173844, '<td valign="top">I understand Tiny''s observations, but still I like this image, especially the cumulus clouds, and find in it a sense of peaceful balance.</td>', 'I understand Tiny''s observations, but still I like this image, especially the cumulus clouds, and find in it a sense of peaceful balance.', '2014-05-06 14:10:04.000000', NULL, 0),
(7213282, 1110921, 173844, '<td valign="top">I like this image very much and gave it a high rating, but didn''t comment because roll-over overtook me.  I love the dark processing that imparts a metallic feel to the foliage that harmonizes with the car''s actual metal.  The heavy overgrowth gives it a feeling of decadence.  I like the way the glass looks.  And I like that it''s right in your face.</td>', 'I like this image very much and gave it a high rating, but didn''t comment because roll-over overtook me.  I love the dark processing that imparts a metallic feel to the foliage that harmonizes with the car''s actual metal.  The heavy overgrowth gives it a feeling of decadence.  I like the way the glass looks.  And I like that it''s right in your face.', '2014-05-06 14:30:45.000000', NULL, 0),
(7213296, 1109945, 173844, '<td valign="top">I gave this image a high rating but roll-over precluded my commenting on it.  Of course it''s her sparkling personality (at least as far as this picture shows) that is the highlight here, but I''m also enamored by how the photo continues to roll out simply to the right.  Joyous.</td>', 'I gave this image a high rating but roll-over precluded my commenting on it.  Of course it''s her sparkling personality (at least as far as this picture shows) that is the highlight here, but I''m also enamored by how the photo continues to roll out simply to the right.  Joyous.', '2014-05-06 14:38:25.000000', NULL, 0),
(7213310, 1110962, 173844, '<td valign="top">Is this entirely black and white?  Hard for me to tell.  In any case, I''m shocked that there are no comments here about this extremely interesting and adroitly composed image.  The first well-placed window admits us to a dark, smoky-toned interior.  The second window,also presented at 45 degrees, opens onto a handsome, atmospheric scene.  It''s three pictures for the price of one.  Bravo!  Seriously under-rated.</td>', 'Is this entirely black and white?  Hard for me to tell.  In any case, I''m shocked that there are no comments here about this extremely interesting and adroitly composed image.  The first well-placed window admits us to a dark, smoky-toned interior.  The second window,also presented at 45 degrees, opens onto a handsome, atmospheric scene.  It''s three pictures for the price of one.  Bravo!  Seriously under-rated.', '2014-05-06 15:07:51.000000', NULL, 0),
(7213316, 1111026, 173844, '<td valign="top">I think this is a very good photo that, unfortunately, and it''s just the way it is, has an immediate background that''s bland in shape and tonality.  There''s a strong sense of lateral movement in the boat, rocks and clouds.  The darker water opens prettily into a sparkling expanse that almost supports the blown out upper reaches.  And yes, it is serene.</td>', 'I think this is a very good photo that, unfortunately, and it''s just the way it is, has an immediate background that''s bland in shape and tonality.  There''s a strong sense of lateral movement in the boat, rocks and clouds.  The darker water opens prettily into a sparkling expanse that almost supports the blown out upper reaches.  And yes, it is serene.', '2014-05-06 15:28:09.000000', NULL, 0),
(7213319, 1110834, 173844, '<td valign="top">Beautifully mysterious.</td>', 'Beautifully mysterious.', '2014-05-06 15:43:40.000000', NULL, 0),
(7213334, 1110865, 67145, '<td valign="top">WOW!! <br/>incredible image .. The series is fantastic ..<br/>Many congrats on the blue .. !!<br/>Ps .. I''ve noticed a drop on my own pics before rollover .. I wonder why that is ..</td>', 'WOW!! incredible image .. The series is fantastic ..Many congrats on the blue .. !!Ps .. I''ve noticed a drop on my own pics before rollover .. I wonder why that is ..', '2014-05-06 16:28:37.000000', NULL, 0),
(7213363, 1110696, 18367, '<td valign="top">I was stunned to find out that this image placed 42 in this challenge.<br/> <br/>I really like this and gave it a 9.<br/> <br/>Goes to show that there are varying tastes when it comes to photography.<br/> <br/>Very nicely done.<br/> <br/>Ray</td>', 'I was stunned to find out that this image placed 42 in this challenge. I really like this and gave it a 9. Goes to show that there are varying tastes when it comes to photography. Very nicely done. Ray', '2014-05-06 19:28:31.000000', NULL, 0),
